mapper.select:
SELECT , d.min_amount, d.max_amount, d.min_month, d.max_month, MIN(br.base_rate_percent) AS min_base_rate_percent, MAX(br.max_rate_percent) AS max_rate_percent, CASE WHEN COUNT(br.base_interest_rate_id) = 1 THEN MAX(br.base_interest_rate_id) ELSE NULL END AS base_interest_rate_id FROM kb_product_version pv JOIN kb_product p ON p.product_id = pv.product_id JOIN deposit d ON d.kb_product_version_id = pv.kb_product_version_id LEFT JOIN base_interest_rate br ON br.kb_product_version_id = pv.kb_product_version_id WHERE 1 = 1
AND pv.kb_product_data_version_id = #{productDataVersionId}
AND pv.kb_product_version_id = #{productVersionId}
GROUP BY pv.kb_product_version_id, pv.kb_product_data_version_id, p.product_id, p.product_code, pv.product_name, p.product_type, pv.description, pv.product_url, pv.sales_status, pv.created_at, d.min_amount, d.max_amount, d.min_month, d.max_month ORDER BY pv.product_name

SELECT , s.savings_category, s.monthly_min_amount, s.monthly_max_amount, s.min_month, s.max_month, MIN(br.base_rate_percent) AS min_base_rate_percent, MAX(br.max_rate_percent) AS max_rate_percent, CASE WHEN COUNT(br.base_interest_rate_id) = 1 THEN MAX(br.base_interest_rate_id) ELSE NULL END AS base_interest_rate_id FROM kb_product_version pv JOIN kb_product p ON p.product_id = pv.product_id JOIN savings s ON s.kb_product_version_id = pv.kb_product_version_id LEFT JOIN base_interest_rate br ON br.kb_product_version_id = pv.kb_product_version_id WHERE 1 = 1
AND pv.kb_product_data_version_id = #{productDataVersionId}
AND pv.kb_product_version_id = #{productVersionId}
GROUP BY pv.kb_product_version_id, pv.kb_product_data_version_id, p.product_id, p.product_code, pv.product_name, p.product_type, pv.description, pv.product_url, pv.sales_status, pv.created_at, s.savings_category, s.monthly_min_amount, s.monthly_max_amount, s.min_month, s.max_month ORDER BY pv.product_name

SELECT , e.stock_code, e.etf_category, e.tracking_index, e.annual_return_10y AS annual_return_10y_percent, e.bond_ratio AS bond_ratio_percent, e.risk_level FROM kb_product_version pv JOIN kb_product p ON p.product_id = pv.product_id JOIN etf e ON e.kb_product_version_id = pv.kb_product_version_id WHERE 1 = 1
AND pv.kb_product_data_version_id = #{productDataVersionId}
AND pv.kb_product_version_id = #{productVersionId}
ORDER BY pv.product_name

mapper.update:
UPDATE kb_product_version
SET product_name = #{productName},
description = #{description},
product_url = #{productUrl},
sales_status = #{salesStatus}
WHERE kb_product_version_id = #{productVersionId}

UPDATE deposit
SET min_amount = #{minAmount},
max_amount = #{maxAmount},
min_month = #{minMonth},
max_month = #{maxMonth}
WHERE kb_product_version_id = #{productVersionId}

UPDATE etf
SET annual_return_10y = #{annualReturn10yPercent}
WHERE kb_product_version_id = #{productVersionId}

mapper.select:
SELECT product_id
FROM kb_product
WHERE product_code = #{productCode}

SELECT product_type
FROM kb_product
WHERE product_code = #{productCode}

SELECT COUNT(*)
FROM kb_product_version
WHERE kb_product_data_version_id = #{productDataVersionId}
  AND product_id = #{productId}

mapper.update:
UPDATE preferential_interest_rate
SET additional_rate_percent = #{additionalRatePercent},
condition_code = #{conditionCode},
preferential_condition = #{preferentialCondition},
base_date = #{baseDate}
WHERE preferential_interest_rate_id = #{preferentialInterestRateId}

mapper.delete:
DELETE eh FROM etf_holding eh
JOIN kb_product_version pv ON pv.kb_product_version_id = eh.kb_product_version_id
WHERE pv.kb_product_data_version_id = #{dataVersionId}

DELETE pr FROM preferential_interest_rate pr
JOIN kb_product_version pv ON pv.kb_product_version_id = pr.kb_product_version_id
WHERE pv.kb_product_data_version_id = #{dataVersionId}

DELETE br FROM base_interest_rate br
JOIN kb_product_version pv ON pv.kb_product_version_id = br.kb_product_version_id
WHERE pv.kb_product_data_version_id = #{dataVersionId}

DELETE e FROM etf e
JOIN kb_product_version pv ON pv.kb_product_version_id = e.kb_product_version_id
WHERE pv.kb_product_data_version_id = #{dataVersionId}

DELETE d FROM deposit d
JOIN kb_product_version pv ON pv.kb_product_version_id = d.kb_product_version_id
WHERE pv.kb_product_data_version_id = #{dataVersionId}

DELETE s FROM savings s
JOIN kb_product_version pv ON pv.kb_product_version_id = s.kb_product_version_id
WHERE pv.kb_product_data_version_id = #{dataVersionId}
